parameters.jsCode:
const d = $('Load Brief Data').first().json;
const llmRaw = $input.first().json || {};
const llm = (llmRaw && typeof llmRaw.output === 'object' && llmRaw.output !== null) ? llmRaw.output : llmRaw;

const qual = Array.isArray(d.qualification) ? d.qualification : [];
const defs = Array.isArray(d.slot_definitions) ? d.slot_definitions : [];
const transcript = Array.isArray(d.transcript) ? d.transcript : [];
const projects = Array.isArray(d.projects) ? d.projects : [];
const booking = d.booking || null;
const agentTz = d.agent_tz || d.market_tz || 'Asia/Dubai';
const currency = d.currency || 'AED';

function fmtMoney(n, cur) {
  const c = cur || currency;
  if (n >= 1000000) return (Math.round((n / 1000000) * 10) / 10) + 'M ' + c;
  if (n >= 1000) return Math.round(n / 1000) + 'K ' + c;
  return n + ' ' + c;
}

function renderValue(v) {
  if (v === null || v === undefined) return 'not given';
  if (typeof v === 'object' && !Array.isArray(v)) {
    if (typeof v.min === 'number' || typeof v.max === 'number') {
      // The band is ours; stated_text is what the lead actually said. The agent
      // needs to see their words, not the number the search was run on.
      if (typeof v.stated_text === 'string' && v.stated_text) {
        if (typeof v.min === 'number' && typeof v.max === 'number') return v.stated_text + ' (searched ' + fmtMoney(v.min, v.currency) + ' to ' + fmtMoney(v.max, v.currency) + ')';
        return v.stated_text;
      }
      if (typeof v.min === 'number' && typeof v.max === 'number') return fmtMoney(v.min, v.currency) + ' to ' + fmtMoney(v.max, v.currency);
      if (typeof v.max === 'number') return 'up to ' + fmtMoney(v.max, v.currency);
      return 'from ' + fmtMoney(v.min, v.currency);
    }
    const bits = [];
    if (v.full_name) bits.push(v.full_name);
    if (v.phone) bits.push(v.phone);
    if (v.email) bits.push(v.email);
    if (bits.length) return bits.join(', ');
    return JSON.stringify(v);
  }
  return String(v);
}

function slotValue(key) {
  for (const q of qual) { if (q.slot_key === key) return q; }
  return null;
}

const meetingLine = (booking && booking.starts_at)
  ? DateTime.fromISO(booking.starts_at).setZone(agentTz).toFormat('cccc d LLLL yyyy, h:mm a') + ' (' + agentTz + ')'
  : 'no meeting booked';

const contact = slotValue('contact');
const contactValue = contact ? contact.value : null;
const displayName = d.lead_name || (contactValue && contactValue.full_name) || 'Unnamed lead';
const phone = d.lead_phone || (contactValue && contactValue.phone) || 'not given';
const email = d.lead_email || (contactValue && contactValue.email) || 'not given';
const residency = slotValue('residency');
const based = residency && residency.value ? renderValue(residency.value) : 'not given';

const block1 = {
  name: displayName,
  phone: phone,
  email: email,
  meeting: meetingLine,
  channel: d.channel || 'unknown',
  based: based
};

const filled = qual.filter(function (q) { return q.state === 'filled' || q.state === 'conflicted'; });
const rawList = filled.map(function (q) { return q.slot_key + ': ' + renderValue(q.value); }).join(', ');
const summary = (typeof llm.summary === 'string' && llm.summary.trim()) ? llm.summary.trim() : (rawList || 'No qualification data captured.');

const flags = [];
for (const c of qual) {
  if (c.state !== 'conflicted') continue;
  const prev = Array.isArray(c.previous_values) ? c.previous_values : [];
  const oldV = prev.length ? prev[prev.length - 1] : null;
  flags.push('Conflicting answers on ' + c.slot_key + ': had ' + renderValue(oldV) + ', now ' + renderValue(c.value) + '.');
}
const exitStrategy = slotValue('exit_strategy');
if (exitStrategy && String(exitStrategy.value) === 'flip') flags.push('Plans to sell before handover, so check the resale threshold on anything you pitch.');
const decisionMaker = slotValue('decision_maker');
if (decisionMaker && decisionMaker.value && String(decisionMaker.value) !== 'solo') flags.push('Not deciding alone (' + renderValue(decisionMaker.value) + ').');
const dodged = qual.filter(function (q) { return q.state === 'unanswered'; }).map(function (q) { return q.slot_key; });
if (dodged.length) flags.push('Dodged after two asks: ' + dodged.join(', ') + '.');
// A required slot that never got an answer used to leave no trace at all: the
// brief simply did not mention it, so the agent had no way to know the gap was
// there. Deferrals ("I'll tell you later") land here.
const answered = {};
for (const q of qual) { if (q.state === 'filled' || q.state === 'conflicted') answered[q.slot_key] = true; }
const missingRequired = defs
  .filter(function (s) { return s.required === true && !answered[s.slot_key] && dodged.indexOf(s.slot_key) === -1; })
  .map(function (s) { return s.slot_key; });
if (missingRequired.length) flags.push('Never answered, worth asking on the call: ' + missingRequired.join(', ') + '.');
if (d.escalation_reason) flags.push('Handed to a human. Reason: ' + d.escalation_reason + '.');

const watchLlm = (typeof llm.watch_out === 'string' && llm.watch_out.trim()) ? llm.watch_out.trim() : '';
const block3Lines = [];
if (watchLlm) block3Lines.push(watchLlm);
for (const f of flags) block3Lines.push(f);
if (block3Lines.length === 0) block3Lines.push('Nothing unusual.');

const shown = [];
for (let i = 0; i < transcript.length; i++) {
  const t = transcript[i];
  if (t.direction !== 'outbound' || !t.body) continue;
  const body = String(t.body).toLowerCase();
  for (const p of projects) {
    const nm = String(p.name || '').toLowerCase();
    if (!nm || body.indexOf(nm) === -1) continue;
    let already = false;
    for (const s of shown) { if (s.project_id === p.id) { already = true; break; } }
    if (already) continue;
    let reacted = false;
    for (let j = i + 1; j < transcript.length; j++) {
      if (transcript[j].direction === 'inbound') {
        const firstWord = nm.split(' ')[0];
        reacted = String(transcript[j].body || '').toLowerCase().indexOf(firstWord) !== -1;
        break;
      }
    }
    shown.push({ project_id: p.id, name: p.name, reacted: reacted });
  }
}

const asked = [];
for (let i = 0; i < transcript.length; i++) {
  const t = transcript[i];
  if (t.direction !== 'inbound' || !t.body) continue;
  if (String(t.body).indexOf('?') === -1) continue;
  let answer = '';
  for (let j = i + 1; j < transcript.length; j++) {
    if (transcript[j].direction === 'outbound') { answer = String(transcript[j].body || ''); break; }
  }
  asked.push({ question: String(t.body), answer: answer });
}

const notCovered = [];
for (const def of defs) {
  const q = slotValue(def.slot_key);
  const st = q ? q.state : 'empty';
  if (st === 'empty' || st === 'unanswered') {
    notCovered.push({ slot_key: def.slot_key, state: st, question: def.question_open });
  }
}

const lines = [];
lines.push('# Lead brief: ' + block1.name);
lines.push('');
lines.push('**Meeting:** ' + block1.meeting);
lines.push('**Phone:** ' + block1.phone + '  |  **Email:** ' + block1.email);
lines.push('**Channel:** ' + block1.channel + '  |  **Based:** ' + block1.based);
lines.push('');
lines.push('## Summary');
lines.push(summary);
lines.push('');
lines.push('## Watch out for');
for (const l of block3Lines) lines.push('- ' + l);
lines.push('');
lines.push('## Shown');
if (shown.length === 0) {
  lines.push('- No specific projects were put in front of them.');
} else {
  for (const s of shown) lines.push('- ' + s.name + (s.reacted ? ' (they came back on this one)' : ' (no reaction)'));
}
lines.push('');
lines.push('## Asked about');
if (asked.length === 0) {
  lines.push('- They asked nothing.');
} else {
  for (const a of asked) lines.push('- They asked: ' + a.question + '\n  We said: ' + (a.answer || 'no reply recorded'));
}
lines.push('');
lines.push('## Not covered');
if (notCovered.length === 0) {
  lines.push('- Everything covered.');
} else {
  for (const n of notCovered) lines.push('- ' + n.slot_key + ' (' + n.state + '): ' + n.question);
}

const markdown = lines.join('\n');

function escapeHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
const telegramText = escapeHtml(markdown.replace(/^#+\s*/gm, '').replace(/\*\*/g, ''));

const blocks = {
  header: block1,
  summary: summary,
  watch_out: block3Lines,
  shown: shown,
  asked: asked,
  not_covered: notCovered
};

return [{ json: {
  conversation_id: d.conversation_id,
  booking_id: booking ? booking.id : '',
  content_markdown: markdown,
  content_blocks_json: JSON.stringify(blocks),
  telegram_text: telegramText.slice(0, 3900),
  calendar_description: markdown.slice(0, 7000),
  subject: 'Lead brief: ' + block1.name + ' - ' + block1.meeting
} }];
